class source_sync_context {
public:
	explicit source_sync_context(falco::semaphore& s):
	        m_finished(false),
	        m_joined(false),
	        m_semaphore(s) {}

	inline void finish() {
		bool v = false;
		while(!m_finished.compare_exchange_weak(v,
		                                        true,
		                                        std::memory_order_seq_cst,
		                                        std::memory_order_seq_cst)) {
			if(v) {
				throw falco_exception("source_sync_context has been finished twice");
			}
		}
		m_semaphore.release();
	}

	inline void join() {
		bool v = false;
		while(!m_joined.compare_exchange_weak(v,
		                                      true,
		                                      std::memory_order_seq_cst,
		                                      std::memory_order_seq_cst)) {
			if(v) {
				throw falco_exception("source_sync_context has been joined twice");
			}
		}
	}

	inline bool joined() { return m_joined.load(std::memory_order_seq_cst); }

	inline bool finished() { return m_finished.load(std::memory_order_seq_cst); }

private:
	// set to true when the event processing loop finishes
	std::atomic<bool> m_finished;
	// set to true when the result has been collected after finishing
	std::atomic<bool> m_joined;
	// used to notify the waiting thread when finished gets set to true
	falco::semaphore& m_semaphore;
};

struct live_context {
	// the name of the source of which events are processed
	std::string source;
	// the result of the event processing loop
	run_result res;
	// if non-null, the thread on which events are processed
	std::unique_ptr<std::thread> thread;
	// used for thread synchronization purposes
	std::unique_ptr<source_sync_context> sync;
};

//
// Event processing loop
//
static falco::app::run_result do_inspect(
        falco::app::state& s,
        std::shared_ptr<sinsp> inspector,
        const std::string& source,  // an empty source represents capture mode
        std::shared_ptr<stats_writer> statsw,
        syscall_evt_drop_mgr& sdropmgr,
        bool check_drops_and_timeouts,
        uint64_t duration_to_tot_ns,
        uint64_t& num_evts) {
	int32_t rc = 0;
	sinsp_evt* ev = NULL;
	stats_writer::collector stats_collector(statsw);
	std::unique_ptr<libs::metrics::libs_metrics_collector> prometheus_metrics_collector;
	prometheus_metrics_refresh prometheus_metrics_refresh;
	uint64_t duration_start = 0;
	uint32_t timeouts_since_last_success_or_msg = 0;
	const bool is_capture_mode = source.empty();
	size_t source_engine_idx = 0;

	// note(jasondellaluce): The "syscall" event source will always be loaded
	// by default in an inspector, and at index 0. As such, in live mode we would
	// expect the event source index to always be 0 in case of "syscall" source,
	// and 1 in case of any other plugin event source, because it would be
	// the only other source loaded in its relative live inspector.
	size_t expected_live_evt_src_idx = source == falco_common::syscall_source ? 0 : 1;

	if(!is_capture_mode) {
		// note: in live mode, each inspector gets assigned a distinct event
		// source that does not change for the whole capture.
		source_engine_idx = s.source_infos.at(source)->engine_idx;
	}

	// reset event counter
	num_evts = 0;

	// init drop manager if we are inspecting syscalls
	if(check_drops_and_timeouts) {
		sdropmgr.init(inspector,
		              s.outputs,  // drop manager has its own rate limiting logic
		              s.config->m_syscall_evt_drop_actions,
		              s.config->m_syscall_evt_drop_threshold,
		              s.config->m_syscall_evt_drop_rate,
		              s.config->m_syscall_evt_drop_max_burst,
		              s.config->m_syscall_evt_simulate_drops);
	}

	// init dumper for captures
	auto dumper = std::make_unique<sinsp_dumper>();
	uint64_t dump_started_ts = 0;
	uint64_t dump_deadline_ts = 0;
	// Global hard cap on capture file size (MB). 0 means unlimited.
	const uint64_t dump_max_file_size_mb = s.config->m_capture_max_file_size_mb;

	//
	// Start capture
	//
	inspector->start_capture();
	if(!is_capture_mode) {
		falco::app::g_reload_state.source_started();
	}

	const bool collect_prometheus_metrics =
	        prometheus_metrics_collection_enabled(*s.config, is_capture_mode);
	if(collect_prometheus_metrics) {
		uint32_t flags = s.config->m_metrics_flags;
		if(!inspector->check_current_engine(MODERN_BPF_ENGINE)) {
			flags &= ~METRICS_V2_LIBBPF_STATS;
		}
		if(source != falco_common::syscall_source) {
			flags &= ~(METRICS_V2_KERNEL_COUNTERS | METRICS_V2_KERNEL_COUNTERS_PER_CPU |
			           METRICS_V2_STATE_COUNTERS | METRICS_V2_LIBBPF_STATS |
			           METRICS_V2_KERNEL_ITER_COUNTERS);
		}
		prometheus_metrics_collector =
		        std::make_unique<libs::metrics::libs_metrics_collector>(inspector.get(), flags);
		auto snapshot_prometheus_metrics = [&]() {
			prometheus_metrics_collector->snapshot();
			s.source_infos.at(source)->set_metrics_snapshot(
			        prometheus_metrics_collector->get_metrics());
		};
		prometheus_metrics_refresh.initialize(snapshot_prometheus_metrics);
	}

	//
	// Loop through the events
	//
	while(1) {
		rc = inspector->next(&ev);

		if(falco::app::g_reopen_outputs_signal.triggered()) {
			falco::app::g_reopen_outputs_signal.handle([&s]() {
				falco_logger::log(falco_logger::level::INFO,
				                  "SIGUSR1 received, reopening outputs...\n");
				if(s.outputs != nullptr) {
					s.outputs->reopen_outputs();
				}
				falco::app::g_reopen_outputs_signal.reset();
			});
		}

		if(falco::app::g_terminate_signal.triggered()) {
			falco::app::g_terminate_signal.handle([&]() {
				falco_logger::log(falco_logger::level::INFO, "SIGINT received, exiting...\n");
				if(dump_started_ts != 0) {
					dump_started_ts = 0;
					dump_deadline_ts = 0;
					dumper->close();
				}
			});
			break;
		} else if(falco::app::g_restart_signal.triggered()) {
			falco::app::g_restart_signal.handle([&]() {
				falco_logger::log(falco_logger::level::INFO, "SIGHUP received, restarting...\n");
				if(dump_started_ts != 0) {
					dump_started_ts = 0;
					dump_deadline_ts = 0;
					dumper->close();
				}
				s.restart.store(true);
			});
			break;
		}

		if(collect_prometheus_metrics) {
			auto snapshot_prometheus_metrics = [&]() {
				prometheus_metrics_collector->snapshot();
				s.source_infos.at(source)->set_metrics_snapshot(
				        prometheus_metrics_collector->get_metrics());
			};
			prometheus_metrics_refresh.refresh_if_due(rc, snapshot_prometheus_metrics);
		}

		if(rc == SCAP_TIMEOUT) {
			if(ev == nullptr) [[unlikely]] {
				timeouts_since_last_success_or_msg++;
				if(timeouts_since_last_success_or_msg >
				           s.config->m_syscall_evt_timeout_max_consecutives &&
				   check_drops_and_timeouts) {
					std::string rule = "Falco internal: timeouts notification";
					std::string msg =
					        rule + ". " +
					        std::to_string(s.config->m_syscall_evt_timeout_max_consecutives) +
					        " consecutive timeouts without event.";
					std::string last_event_time_str = "none";
					if(duration_start > 0) {
						sinsp_utils::ts_to_string(duration_start,
						                          &last_event_time_str,
						                          false,
						                          true);
					}
					nlohmann::json fields;
					fields["last_event_time"] = last_event_time_str;
					auto now = std::chrono::duration_cast<std::chrono::nanoseconds>(
					                   std::chrono::system_clock::now().time_since_epoch())
					                   .count();

