#include <libsinsp/plugin_manager.h>

using namespace falco::app;
using namespace falco::app::actions;

static void extract_base_syscalls_names(const std::unordered_set<std::string>& base_syscalls_names,
                                        std::unordered_set<std::string>& user_positive_names,
                                        std::unordered_set<std::string>& user_negative_names) {
	for(const std::string& ev : base_syscalls_names) {
		if(!ev.empty()) {
			if(ev.at(0) == '!') {
				user_negative_names.insert(ev.substr(1, ev.size()));
			} else {
				user_positive_names.insert(ev);
			}
		}
	}
}

static void check_for_rules_unsupported_events(
        falco::app::state& s,
        const libsinsp::events::set<ppm_sc_code>& rules_sc_set) {
	/* When replaying a capture the selected event set does not apply:
	 * the file contains whatever was recorded, so there is nothing to warn about. */
	if(s.is_replaying()) {
		return;
	}

	/* Unsupported events are those events that are used in the rules
	 * but that are not part of the selected event set. For now, this
	 * is expected to happen only for high volume syscalls for
	 * performance reasons. */
	auto unsupported_sc_set = rules_sc_set.diff(s.selected_sc_set);
	if(unsupported_sc_set.empty()) {
		return;
	}

	/* Get the names of the events (syscall and non syscall events) that were not activated and
	 * print them. */
	auto names = libsinsp::events::sc_set_to_event_names(unsupported_sc_set);
	std::cerr
	        << "Loaded rules match syscalls that are not activated (e.g. were removed via config "
	           "settings such as `base_syscalls.all: false` or negative `base_syscalls.custom_set` "
	           "elements) or unsupported with current configuration: warning "
	           "(unsupported-evttype): " +
	                   concat_set_in_order(names)
	        << std::endl;
	std::cerr << "If syscalls in rules include high volume syscalls (-> activate via "
	             "`base_syscalls.all: true`), else syscalls may have been removed via the "
	             "`base_syscalls.custom_set` option or might be "
	             "associated with syscalls undefined on your architecture "
	             "(https://marcin.juszkiewicz.com.pl/download/tables/syscalls.html)"
	          << std::endl;
}

static void select_event_set(falco::app::state& s,
                             const libsinsp::events::set<ppm_sc_code>& rules_sc_set) {
	/* PPM syscall codes (sc) can be viewed as condensed libsinsp lookup table
	 * to map a system call name to it's actual system syscall id (as defined
	 * by the Linux kernel). Hence here we don't need syscall enter and exit distinction. */
	auto rules_names = libsinsp::events::sc_set_to_event_names(rules_sc_set);
	if(!rules_sc_set.empty()) {
		falco_logger::log(falco_logger::level::DEBUG,
		                  "(" + std::to_string(rules_names.size()) + ") syscalls in rules: " +
		                          concat_set_in_order(rules_names) + "\n");
