		falco_logger::log(falco_logger::level::DEBUG,
		                  "+(" + std::to_string(user_positive_sc_set_names.size()) +
		                          ") syscalls added (base_syscalls override): " +
		                          concat_set_in_order(user_positive_sc_set_names) + "\n");
