			        falco_logger::level::DEBUG,
			        "-(" + std::to_string(erased_sc_set_names.size()) +
			                ") ignored syscalls (-> activate via `base_syscalls.all: true`): " +
			                concat_set_in_order(erased_sc_set_names) + "\n");
