static void fdinfo_from_task_file_regular_evt(scap_fdinfo *fdinfo,
                                              const scap_const_sized_buffer *evt_params) {
	fdinfo->type = SCAP_FD_FILE_V2;
	i64_from_i32_param(&fdinfo->fd, &evt_params[0]);                  // fd
