bool wait_for_file(const std::string& path) {
	for(int i = 0; i < 1000; i++) {
		if(access(path.c_str(), F_OK) == 0) {
			return true;
		}
		std::this_thread::sleep_for(std::chrono::milliseconds(10));
	}
	return false;
