uint64_t falco_engine::num_rules_for_ruleset(const std::string &ruleset) {
	uint16_t ruleset_id = find_ruleset_id(ruleset);
	uint64_t ret = 0;
	for(const auto &src : m_sources) {
		ret += src.ruleset->enabled_count(ruleset_id);
	}
	return ret;
}

