namespace falco {

// Represents the result of loading a rules file.
class load_result {
public:
	enum error_code {
		LOAD_ERR_FILE_READ = 0,
		LOAD_ERR_YAML_PARSE,
		LOAD_ERR_YAML_VALIDATE,
		LOAD_ERR_COMPILE_CONDITION,
		LOAD_ERR_COMPILE_OUTPUT,
		LOAD_ERR_VALIDATE,
		LOAD_ERR_EXTENSION
	};

	// The error code as a string
